CREATE OR REPLACE FUNCTION public.intranet_can_access(p_sector text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND p_sector IN ('comercial','marketing','administracao','financeiro','desenvolvimento') AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role::text IN ('master','senior') OR role::text=p_sector OR (p_sector='administracao' AND role::text='admin' AND NOT EXISTS(SELECT 1 FROM public.user_roles x WHERE x.user_id=auth.uid() AND x.role::text IN ('financeiro','comercial','marketing','desenvolvimento'))))); $$;
REVOKE ALL ON FUNCTION public.intranet_can_access(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intranet_can_access(text) TO authenticated,service_role;
CREATE TABLE public.intranet_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company text NOT NULL CHECK(length(trim(company)) BETWEEN 1 AND 160),contact text NOT NULL DEFAULT '' CHECK(length(contact)<=200),stage text NOT NULL DEFAULT 'novo' CHECK(stage IN ('novo','contato','proposta','ganho','perdido')),monthly_cents integer NOT NULL DEFAULT 0 CHECK(monthly_cents>=0),starts_on date,ends_on date,notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_on IS NULL OR starts_on IS NULL OR ends_on>=starts_on));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.intranet_leads TO authenticated; GRANT ALL ON public.intranet_leads TO service_role;
ALTER TABLE public.intranet_leads ENABLE ROW LEVEL SECURITY; CREATE POLICY leads_sector ON public.intranet_leads TO authenticated USING(public.intranet_can_access('comercial')) WITH CHECK(public.intranet_can_access('comercial'));
CREATE TABLE public.intranet_campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 160),channel text NOT NULL CHECK(channel IN ('organico','pago')),destination text NOT NULL CHECK(destination ~ '^https://'),status text NOT NULL DEFAULT 'planejada' CHECK(status IN ('planejada','ativa','encerrada')),budget_cents integer NOT NULL DEFAULT 0 CHECK(budget_cents>=0),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.intranet_campaigns TO authenticated; GRANT ALL ON public.intranet_campaigns TO service_role;
ALTER TABLE public.intranet_campaigns ENABLE ROW LEVEL SECURITY; CREATE POLICY campaigns_sector ON public.intranet_campaigns TO authenticated USING(public.intranet_can_access('marketing')) WITH CHECK(public.intranet_can_access('marketing'));
CREATE TABLE public.intranet_health_samples(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),latency_ms integer NOT NULL CHECK(latency_ms BETWEEN 0 AND 600000),storage_used bigint CHECK(storage_used>=0),storage_quota bigint CHECK(storage_quota>=0),created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.intranet_health_samples TO authenticated; GRANT ALL ON public.intranet_health_samples TO service_role;
ALTER TABLE public.intranet_health_samples ENABLE ROW LEVEL SECURITY; CREATE POLICY health_read ON public.intranet_health_samples FOR SELECT TO authenticated USING(public.intranet_can_access('desenvolvimento')); CREATE POLICY health_write ON public.intranet_health_samples FOR INSERT TO authenticated WITH CHECK(public.intranet_can_access('desenvolvimento') AND created_by=auth.uid());
CREATE OR REPLACE FUNCTION public.intranet_dashboard(p_sector text,p_days integer DEFAULT 30) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; since timestamptz:=now()-make_interval(days=>p_days); BEGIN
IF NOT public.intranet_can_access(p_sector) THEN RAISE EXCEPTION 'Sem acesso a este setor' USING ERRCODE='42501'; END IF; IF p_days NOT IN (7,30,90) THEN RAISE EXCEPTION 'Período inválido'; END IF;
result:=jsonb_build_object('summary',jsonb_build_object('submissions',(SELECT count(*) FROM public.submissions WHERE deleted_at IS NULL AND created_at>=since),'pending',(SELECT count(*) FROM public.submissions WHERE deleted_at IS NULL AND status='pendente'),'users',(SELECT count(*) FROM public.profiles WHERE created_at>=since),'received_cents',(SELECT coalesce(sum(amount_cents),0) FROM public.payment_records WHERE settled_at>=since)),'consolidated',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM (SELECT (created_at AT TIME ZONE 'America/Sao_Paulo')::date::text name,count(*) value FROM public.submissions WHERE deleted_at IS NULL AND created_at>=since GROUP BY 1 ORDER BY 1) t));
IF p_sector='administracao' THEN result:=result||jsonb_build_object('moderation_hours',(SELECT round(avg(extract(epoch FROM(coalesce(approved_at,rejected_at)-created_at))/3600)::numeric,1) FROM public.submissions WHERE deleted_at IS NULL AND created_at>=since AND coalesce(approved_at,rejected_at)>=created_at),'ranking',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM(SELECT coalesce(nullif(location,''),'Local não informado') name,count(*) value FROM public.submissions WHERE deleted_at IS NULL AND created_at>=since GROUP BY 1 ORDER BY 2 DESC LIMIT 10)t),'queue',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM(SELECT id,event_title,date,start_time,location,promotion_choice FROM public.submissions WHERE deleted_at IS NULL AND status='pendente' ORDER BY created_at LIMIT 100)t));
ELSIF p_sector='comercial' THEN result:=result||jsonb_build_object('inventory',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM(SELECT p.name,count(a.id) FILTER(WHERE a.status='publicado' AND (a.highlight_until IS NULL OR a.highlight_until>now())) value FROM public.ad_products p LEFT JOIN public.ads a ON a.product_id=p.id WHERE p.is_active GROUP BY p.id,p.name)t),'ads',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM(SELECT a.title,a.status,a.highlight_until,a.target_regions,p.name product FROM public.ads a LEFT JOIN public.ad_products p ON p.id=a.product_id WHERE a.product_id IS NOT NULL ORDER BY a.created_at DESC LIMIT 100)t));
ELSIF p_sector='marketing' THEN result:=result||jsonb_build_object('growth',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM(SELECT (created_at AT TIME ZONE 'America/Sao_Paulo')::date::text name,count(*) value FROM public.profiles WHERE created_at>=since GROUP BY 1 ORDER BY 1)t)); END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.intranet_dashboard(text,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.intranet_dashboard(text,integer) TO authenticated,service_role;